select id, coupon_codes, exists(coupon_codes, c -> c like 'W%') as has_welcome_code, coalesce(attributes['utm_source'], 'direct') as utm_source_or_default, ship_to.city as ship_city, attributes['device'] as device, transform(filter(items, item -> item.promo is not null), item -> struct(item.product_id as pid, round(item.price * 0.9, 2) as discounted_price)) as promo_lines from carts where array_contains(coupon_codes, 'BUNDLE')
